"""Shared pieces of the Lua-configured backends (wasp, spitfire).

Both WMs take a Lua config that is code, not data. Kantele never rewrites it:
it owns a generated kantele.lua that config.lua loads from its last line, and
it reads the current values by running config.lua with the system Lua.
"""

from __future__ import annotations

import json
import os
import re
import shutil
import subprocess
from dataclasses import dataclass
from pathlib import Path

LUA = "lua5.4"

HEADER = """\
-- Generated by Kantele (https://github.com/dani-77/kantele). Don't edit:
-- Kantele rewrites this file on every save. Delete it to drop every
-- Kantele setting; config.lua loads it from its last line.

"""

# enc(value) -> JSON text. Functions and userdata are skipped, cycles become
# null; integer-keyed tables 1..n are arrays.
ENC_LUA = r'''
local function enc(v, seen)
  seen = seen or {}
  local t = type(v)
  if t == "nil" then return "null"
  elseif t == "boolean" then return tostring(v)
  elseif t == "number" then
    if v ~= v or v == math.huge or v == -math.huge then return "null" end
    if math.type(v) == "integer" then return tostring(v) end
    return string.format("%.14g", v)
  elseif t == "string" then
    return '"' .. v:gsub('[%c"\\]', function(c)
      return string.format("\\u%04x", c:byte())
    end) .. '"'
  elseif t == "table" then
    if seen[v] then return "null" end
    seen[v] = true
    local n = rawlen(v)
    local out = {}
    local is_array = n > 0
    for k in next, v do
      if math.type(k) ~= "integer" or k < 1 or k > n then is_array = false break end
    end
    if is_array then
      for i = 1, n do out[#out + 1] = enc(rawget(v, i), seen) end
      seen[v] = nil
      return "[" .. table.concat(out, ",") .. "]"
    end
    for k, x in next, v do
      if type(k) == "string" and type(x) ~= "function" and type(x) ~= "userdata" then
        out[#out + 1] = enc(k, seen) .. ":" .. enc(x, seen)
      end
    end
    seen[v] = nil
    return "{" .. table.concat(out, ",") .. "}"
  end
  return "null"
end
'''


class LuaError(RuntimeError):
    pass


def run(script: str, file: Path, *args: str):
    """Runs `script` with arg[1] = file and the rest of `args`, from the
    file's directory, and returns its stdout parsed as JSON."""
    if not shutil.which(LUA):
        raise LuaError(f"{LUA} not found; Kantele needs it to read Lua configs.")
    p = subprocess.run([LUA, "-", str(file), *args], input=ENC_LUA + script,
                       capture_output=True, text=True, timeout=10, cwd=file.parent)
    if p.returncode != 0:
        raise LuaError(p.stderr.strip() or f"{LUA} exited with {p.returncode}")
    return json.loads(p.stdout or "null")


def lua_literal(v, indent: str = "") -> str:
    """Python value -> Lua source. Dicts keep their order, so the output is
    stable and a no-op save rewrites kantele.lua byte for byte."""
    if v is None:
        return "nil"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return repr(v)
    if isinstance(v, str):
        out = v.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
        out = re.sub(r"[\x00-\x1f\x7f]", lambda m: "\\%03d" % ord(m.group()), out)
        return f'"{out}"'
    if isinstance(v, list):
        if all(not isinstance(x, (dict, list)) for x in v):
            return "{ " + ", ".join(lua_literal(x) for x in v) + " }" if v else "{}"
        inner = indent + "  "
        return "{\n" + "".join(f"{inner}{lua_literal(x, inner)},\n" for x in v) + indent + "}"
    if isinstance(v, dict):
        if not v:
            return "{}"
        inner = indent + "  "
        items = []
        for k, x in v.items():
            key = k if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", k) else f"[{lua_literal(k)}]"
            items.append(f"{key} = {lua_literal(x, inner)}")
        one = "{ " + ", ".join(items) + " }"
        if len(one) <= 80 and "\n" not in one:
            return one
        return "{\n" + "".join(f"{inner}{i},\n" for i in items) + indent + "}"
    raise TypeError(f"can't write {type(v).__name__} to Lua")


def atomic_write(path: Path, text: str) -> None:
    tmp = path.with_name(path.name + ".kantele-tmp")
    tmp.write_text(text)
    os.replace(tmp, path)


@dataclass(frozen=True)
class Spec:
    """One scalar setting: where it lives in the WM's table and how to edit it."""

    path: tuple[str, ...]
    label: str
    kind: str  # "int" | "float" | "bool" | "color" | "str" | "argv" | "choice"
    default: object
    lo: float = 0
    hi: float = 0
    choices: tuple[str, ...] = ()


def get_path(t, path: tuple[str, ...]):
    for k in path:
        if not isinstance(t, dict) or k not in t:
            return None
        t = t[k]
    return t


def coerce(spec: Spec, v):
    """A value read from Lua, made to fit the spec (None -> default)."""
    if v is None:
        return spec.default
    try:
        if spec.kind == "int":
            return int(v)
        if spec.kind == "float":
            return float(v)
        if spec.kind == "bool":
            return bool(v)
        if spec.kind == "argv":
            return [str(x) for x in v] if isinstance(v, list) else spec.default
        return str(v)
    except (TypeError, ValueError):
        return spec.default


def overrides_tree(specs: list[Spec], values: dict, base: dict) -> dict:
    """The settings that differ from config.lua's, as nested dicts in spec order."""
    tree: dict = {}
    for spec in specs:
        v = values.get(spec.path)
        if v == base.get(spec.path):
            continue
        t = tree
        for k in spec.path[:-1]:
            t = t.setdefault(k, {})
        t[spec.path[-1]] = v
    return tree


def add_loader(path: Path, mark: str, loader: str) -> Path | None:
    """Appends the loader line to config.lua if it isn't there yet. The first
    time, keeps a copy of the original next to it and returns its path."""
    text = path.read_text()
    if mark in text:
        return None
    backup = None
    bak = path.with_name(path.name + ".kantele-bak")
    if not bak.exists():
        shutil.copy2(path, bak)
        backup = bak
    sep = "" if text.endswith("\n") or not text else "\n"
    atomic_write(path, text + sep + "\n" + loader)
    return backup


def write_checked(overrides: Path, text: str, check) -> None:
    """Writes kantele.lua, then calls check(); if that raises, puts the old
    file back (or removes the new one) and re-raises."""
    old = overrides.read_text() if overrides.exists() else None
    if text == old:
        return
    atomic_write(overrides, text)
    try:
        check()
    except LuaError:
        if old is None:
            overrides.unlink()
        else:
            atomic_write(overrides, old)
        raise
